    // Explicitly set self-links for a standalone, not-in-list node
    _new->next = _new;
    _new->prev = _new;
} else if (new_linked != 0 && new_linked != 1) {
    // Unknown attribute value: normalize to unlinked
    _new->next = _new;
    _new->prev = _new;
    new_linked = 0;
}
if (new_linked == 1) {
    // Node claims to be linked already; we cannot safely reinsert
    FUZZ_BAIL();
}
// Call target: insert _new before head (at tail)
